// Offline support. Serves files from the cache straight away and refreshes the
// cache in the background, so the next launch picks up any update.
// Generated by scripts/build-sw.mjs: re-run it after changing app files.
const CACHE = 'dressup-world-tour-202610261353';
const ASSETS = [
  './',
  'css/styles.css',
  'icons/apple-touch-icon.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon.svg',
  'index.html',
  'js/audio.js',
  'js/data/countries.js',
  'js/data/worldmap.js',
  'js/doll.js',
  'js/items.js',
  'js/learn.js',
  'js/main.js',
  'js/scenes.js',
  'js/screens/collections.js',
  'js/screens/home.js',
  'js/screens/map.js',
  'js/screens/studio.js',
  'js/screens/trip.js',
  'js/store.js',
  'js/svg.js',
  'js/ui.js',
  'js/util.js',
  'manifest.webmanifest'
];

self.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(ASSETS)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith(caches.open(CACHE).then(async cache => {
    const hit = await cache.match(req, { ignoreSearch: true });
    const fresh = fetch(req)
      .then(res => { if (res.ok) cache.put(req, res.clone()); return res; })
      .catch(() => hit || cache.match('index.html'));
    return hit || fresh;
  }));
});
